  left_join(data_list[[5]] %>% select(NSID, starts_with('W9ACQU'), starts_with('W9VCQU')), by = 'NSID') %>%
  left_join(data_list[[6]] %>% select(NSID, W9DANVQH, W9DVNVQH), by = 'NSID')

