# NVQ Mapping for W8VCQU variables
# NVQ 4-5: HNC/HND(K), ONC/OND(L), NVQ L3-5(J)
# NVQ 1-3: Youth Training(A), Key Skills(B), Basic Skills(C), Wales Entry(D), Apprenticeship(E), RSA/OCR(F), City Guilds(G), GNVQ/GSVQ(H), NVQ L1-2(I), BTEC/BEC(M), SCOTVEC(N), Other(O)
# Entry/None: None(P)

map_voc_w8 <- function(row) {
  # Highest qualification first
  if (row[['W8VCQU0K']] == 1 || row[['W8VCQU0L']] == 1 || row[['W8VCQU0J']] == 1) return(0)

  # NVQ 1-3
  if (any(row[c('W8VCQU0A', 'W8VCQU0B', 'W8VCQU0C', 'W8VCQU0D', 'W8VCQU0E', 'W8VCQU0F', 'W8VCQU0G', 'W8VCQU0H', 'W8VCQU0I', 'W8VCQU0M', 'W8VCQU0N', 'W8VCQU0O')] == 1)) return(1)

  # Entry/None
  if (row[['W8VCQU0P']] == 1) return(2)

  # Other
  return(3)
}

