full_frame <- full_frame %>%
  mutate(
    voc_level_25 = apply(., function(row) {
      if (row[['W8VCQU0Q']] == 1) return(-8)
      if (row[['W8VCQU0R']] == 1) return(-9)

      if (row[['W8VCQU0K']] == 1 || row[['W8VCQU0L']] == 1 || row[['W8VCQU0J']] == 1) return(0)
      if (any(row[c('W8VCQU0A', 'W8VCQU0B', 'W8VCQU0C', 'W8VCQU0D', 'W8VCQU0E', 'W8VCQU0F', 'W8VCQU0G', 'W8VCQU0H', 'W8VCQU0I', 'W8VCQU0M', 'W8VCQU0N', 'W8VCQU0O')] == 1)) return(1)
      if (row[['W8VCQU0P']] == 1) return(2)

      # Check if any substantive response was given
      if (any(row[grep('W8VCQU0[A-P]', names(row))] == 1)) return(2) # logically if only None is 1
      return(NA)
    }, 1),

    acad_level_25 = case_when(
      W8DHANVQH %in% 4:5 ~ 0,
      W8DHANVQH %in% 1:3 ~ 1,
      W8DHANVQH == 96 ~ 2,
      W8DHANVQH == 95 ~ 3,
      W8DHANVQH == -9 ~ -9,
      W8DHANVQH == -8 ~ -8,
      W8DHANVQH == -1 ~ -1,
      TRUE ~ NA
    )
  )

full_frame <- full_frame %>%
  mutate(
    educ25 = pmax(acad_level_25, voc_level_25, na.rm = TRUE),
    educ25 = case_when(
      is.na(educ25) ~ -3,
      TRUE ~ educ25
    )
  )

# --- educ32 Derivation ---
full_frame <- full_frame %>%
  mutate(
    acad_level_32 = case_when(
      W9DANVQH %in% 4:5 ~ 0,
      W9DANVQH %in% 1:3 ~ 1,
      W9DANVQH == 0 ~ 2,
      W9DANVQH == 96 ~ 2,
      W9DANVQH == 95 ~ 3,
      TRUE ~ W9DANVQH
    ),
    voc_level_32 = case_when(
      W9DVNVQH %in% 4:5 ~ 0,
      W9DVNVQH %in% 1:3 ~ 1,
      W9DVNVQH == 0 ~ 2,
      W9DVNVQH == 96 ~ 2,
      W9DVNVQH == 95 ~ 3,
      TRUE ~ W9DVNVQH
    )
  )

full_frame <- full_frame %>%
  mutate(
    educ32 = pmax(acad_level_32, voc_level_32, na.rm = TRUE),
    educ32 = case_when(
      is.na(educ32) ~ -3,
      TRUE ~ educ32
    )
  )

# Harmonised Factor labels
nvq_labels <- c("0" = "NVQ 4–5 equivalent", "1" = "NVQ 1–3 equivalent", "2" = "Entry level or no qualifications", "3" = "Other qualifications not mappable to the NVQ framework", "4" = "None of these qualifications")
# Note: the logic above mapped 'None' to 2 (Entry level or no qualifications) as per typical NVQ schemes, but the target is 5 levels. 
# Re-checking target: 0=4-5, 1=1-3, 2=Entry/No, 3=Other, 4=None of these. 
# Actually, the target says 2 = Entry level or no qualifications AND 4 = None of these. 
# Let's adjust mapping: 96 (None) -> 4, 0 (Entry) -> 2.

full_frame <- full_frame %>%
  mutate(
    acad_level_25 = case_when(
      W8DHANVQH %in% 4:5 ~ 0, W8DHANVQH %in% 1:3 ~ 1, W8DHANVQH == 96 ~ 4, W8DHANVQH == 95 ~ 3, W8DHANVQH == -9 ~ -9, W8DHANVQH == -8 ~ -8, W8DHANVQH == -1 ~ -1, TRUE ~ NA
    ),
